tasks.solution:
kubectl -n ws-04 create configmap site --from-literal=index.html=hello-cm
kubectl -n ws-04 patch deploy web --type=json -p='[
  {"op":"add","path":"/spec/template/spec/volumes","value":[{"name":"site","configMap":{"name":"site"}}]},
  {"op":"add","path":"/spec/template/spec/containers/0/volumeMounts","value":[{"name":"site","mountPath":"/usr/share/nginx/html/index.html","subPath":"index.html"}]}
]'
kubectl -n ws-04 rollout status deploy/web

kubectl -n tr-03 patch deploy web --type=json -p='[
  {"op":"replace","path":"/spec/template/spec/containers/0/readinessProbe","value":{"httpGet":{"path":"/","port":80}}}
]'
kubectl -n tr-03 rollout status deploy/web

